function Get-TaskForgeStatistics {
    param([AllowEmptyCollection()][object[]]$Tasks)

    $items = @($Tasks)
    $total = $items.Count
    $completed = @($items | Where-Object { $_.status -eq 'completed' }).Count
    $pending = @($items | Where-Object { $_.status -eq 'pending' }).Count

    if ($total -eq 0) {
        $percentage = [double]0.0
    }
    else {
        $percentage = [math]::Round(($completed / $total) * 100, 1, [System.MidpointRounding]::AwayFromZero)
    }

    $counts = @{}
    foreach ($item in $items) {
        $moment = [DateTimeOffset]::Parse(
            [string]$item.createdAt,
            [System.Globalization.CultureInfo]::InvariantCulture,
            [System.Globalization.DateTimeStyles]::RoundtripKind)
        $day = $moment.UtcDateTime.ToString('yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
        if ($counts.ContainsKey($day)) {
            $counts[$day] = $counts[$day] + 1
        }
        else {
            $counts[$day] = 1
        }
    }

    $createdByDate = @(
        $counts.GetEnumerator() |
            Sort-Object -Property Key |
            ForEach-Object { [ordered]@{ date = [string]$_.Key; count = [int]$_.Value } }
    )

    return [ordered]@{
        total = [int]$total
        pending = [int]$pending
        completed = [int]$completed
        completionPercentage = [double]$percentage
        createdByDate = $createdByDate
    }
}

